def f(inp):
    out=[r[:] for r in inp]
    rows2=[i for i,r in enumerate(inp) if 2 in r]
    # contiguous group boundaries -> find gap rows (no 2) strictly between shape rows
    gaps=[]
    prev=None
    for i in rows2:
        if prev is not None and i-prev>1:
            gaps.append((prev+1,i-1))
        prev=i
    for a,b in gaps:
        for j in range(a,b+1):
            out[j]=[3]*len(out[0])
    return out
